import { Component, inject, signal } from '@angular/core';
import { form, FormField, required } from '@angular/forms/signals';
import { MAT_DIALOG_DATA, MatDialogRef } from '@angular/material/dialog';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { MatSelectModule } from '@angular/material/select';
import {
    BuildingLevel,
    getInvalidSignalFields,
    i18n,
    notifyError,
    OrganisationService,
} from '@placeos/common';
import {
    FullscreenModalShellComponent,
    SettingsToggleComponent,
    TranslatePipe,
} from '@placeos/components';
import { addZone, authority, updateZone } from '@placeos/ts-client';
import { errorText } from '../ui/modal-actions';

@Component({
    selector: 'level-modal',
    template: `
        <fullscreen-modal-shell
            [heading]="
                (model().id
                    ? 'APP.CONCIERGE.LEVELS_EDIT'
                    : 'APP.CONCIERGE.LEVELS_NEW'
                ) | translate
            "
            [loading]="
                loading() ? ('APP.CONCIERGE.LEVELS_SAVING' | translate) : ''
            "
            (confirm)="save()"
        >
            <form system>
                <div class="flex flex-col">
                    <label
                        for="zone"
                        [class.error]="
                            form.parent_id().invalid() &&
                            form.parent_id().touched()
                        "
                    >
                        {{ 'RESOURCE.BUILDING' | translate }}<span>*</span>
                    </label>
                    <mat-form-field appearance="outline">
                        <mat-select
                            [formField]="form.parent_id"
                            [placeholder]="'COMMON.BUILDING_SELECT' | translate"
                        >
                            @for (
                                building of building_list();
                                track building.id
                            ) {
                                <mat-option [value]="building.id">
                                    {{ building.display_name || building.name }}
                                </mat-option>
                            }
                        </mat-select>
                        <mat-error>{{
                            'APP.CONCIERGE.LEVELS_BUILDING_REQUIRED' | translate
                        }}</mat-error>
                    </mat-form-field>
                </div>
                <div class="flex flex-col">
                    <label for="display-name">{{
                        'FORM.DISPLAY_NAME' | translate
                    }}</label>
                    <mat-form-field appearance="outline">
                        <input
                            matInput
                            [placeholder]="'FORM.DISPLAY_NAME' | translate"
                            [formField]="form.display_name"
                        />
                    </mat-form-field>
                </div>
                <div class="flex space-x-4 pb-4">
                    <settings-toggle
                        class="flex-1"
                        [label]="'APP.CONCIERGE.LEVELS_HAS_PARKING' | translate"
                        [formField]="form.parking"
                    >
                    </settings-toggle>
                    <div class="flex-1"></div>
                </div>
                <div class="flex flex-col">
                    <label for="map-id">{{
                        'APP.CONCIERGE.LEVELS_MAP_URL' | translate
                    }}</label>
                    <mat-form-field appearance="outline">
                        <input
                            matInput
                            [placeholder]="
                                'APP.CONCIERGE.LEVELS_MAP_URL_PLACEHOLDER'
                                    | translate
                            "
                            [formField]="form.map_id"
                        />
                    </mat-form-field>
                </div>
            </form>
        </fullscreen-modal-shell>
    `,
    styles: [``],
    imports: [
        FullscreenModalShellComponent,
        MatFormFieldModule,
        MatInputModule,
        FormField,
        SettingsToggleComponent,
        MatSelectModule,
        TranslatePipe,
    ],
})
export class LevelModalComponent {
    private _org = inject(OrganisationService);
    private _data = inject<BuildingLevel | undefined>(MAT_DIALOG_DATA);
    private _dialog_ref =
        inject<MatDialogRef<LevelModalComponent>>(MatDialogRef);

    public readonly loading = signal(false);
    public readonly building_list = this._org.building_list;

    public readonly model = signal({
        id: this._data?.id || '',
        display_name: this._data?.display_name || '',
        parent_id: this._data?.parent_id || '',
        map_id: this._data?.map_id || '',
        parking: this._data?.tags?.includes('parking') || false,
    });

    public readonly form = form(this.model, (p) => {
        required(p.display_name);
        required(p.parent_id);
        required(p.map_id);
    });

    public async save() {
        this.form().markAsTouched();
        if (!this.form().valid()) {
            return notifyError(
                i18n('FORM.INVALID_FIELDS', {
                    field_list: getInvalidSignalFields(
                        this.form,
                        this.model,
                    ).join(', '),
                }),
            );
        }
        this.loading.set(true);
        const data: any = this.model();
        data.tags = data.parking ? ['level', 'parking'] : ['level'];
        const body = {
            ...data,
            name: `LEVEL ${authority().description} ${data.display_name}`,
        };
        try {
            const resp = await (data.id
                ? updateZone(data.id, body)
                : addZone(body));
            this._dialog_ref.close(resp);
        } catch (e) {
            notifyError(`Failed to save level. ${errorText(e)}`);
        } finally {
            this.loading.set(false);
        }
    }
}
